<?php
 namespace Pterodactyl\Console\Commands\Dezerx; use Throwable; use Illuminate\Console\Command; use Pterodactyl\Services\Dezerx\ServerCreate\ServerCreate; use Pterodactyl\Services\Dezerx\ServerCreate\RenewalRunner; class RunServerRenewals extends Command { protected $signature = 'dezerx:run-server-renewals'; protected $description = 'Suspends or deletes every self-created server whose renewal date has passed.'; public function handle(RenewalRunner $runner): int { if (!ServerCreate::enabled() || !ServerCreate::renewals()) { return self::SUCCESS; } $backfilled = $runner->backfill(); if ($backfilled > 0) { $this->line("Gave $backfilled server(s) a first renewal date."); } $ran = 0; foreach ($runner->due() as $entry) { try { $outcome = $runner->handle($entry); $ran++; $this->line("Server {$entry->server_id}: {$outcome}."); } catch (Throwable $exception) { $runner->fail($entry, $exception); $this->warn("Server {$entry->server_id}: {$exception->getMessage()}"); } } foreach ($runner->purgeable() as $entry) { try { $outcome = $runner->purge($entry); $ran++; $this->line("Server {$entry->server_id}: {$outcome}."); } catch (Throwable $exception) { $runner->fail($entry, $exception); $this->warn("Server {$entry->server_id}: {$exception->getMessage()}"); } } if ($ran > 0) { $this->info("Dealt with $ran server" . ($ran === 1 ? '.' : 's.')); } return self::SUCCESS; } } 